package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeBindings_create_TriageGen2Test {

    /**
     * Mock class with exactly one type parameter to satisfy the varLen == 1 condition.
     */
    public static class SingleParam<T> {
    }

    /**
     * Mock class with zero type parameters.
     */
    public static class ZeroParams {
    }

    /**
     * Mock class with two type parameters.
     */
    public static class TwoParams<T, U> {
    }

    /**
     * Mock class with no type parameters (redundant but for clarity).
     */
    public static class NoParams {
    }

    @Test
    public void testCreate_Success() {
        TypeFactory<?> factory = TypeFactory.defaultInstance();
        JavaType typeArg1 = factory.concretizeType(factory.constructType(String.class));

        // Should succeed for class with exactly 1 type parameter
        TypeBindings result = TypeBindings.create(SingleParam.class, typeArg1);

        Assert.assertNotNull(result);
        Assert.assertFalse(result.isEmpty());
        Assert.assertEquals(1, result.size());
        // The name should match the type variable name in SingleParam<T>
        Assert.assertEquals("T", result.getBoundName(0));
        Assert.assertEquals(typeArg1, result.getBoundType(0));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreate_ThrowsException_WhenZeroParams() {
        TypeFactory<?> factory = TypeFactory.defaultInstance();
        JavaType typeArg1 = factory.concretizeType(factory.constructType(String.class));

        // Should throw IllegalArgumentException because varLen is 0
        TypeBindings.create(ZeroParams.class, typeArg1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreate_ThrowsException_WhenTwoParams() {
        TypeFactory<?> factory = TypeFactory.defaultInstance();
        JavaType typeArg1 = factory.concretizeType(factory.constructType(String.class));

        // Should throw IllegalArgumentException because varLen is 2
        TypeBindings.create(TwoParams.class, typeArg1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreate_ThrowsException_WhenNullClass() {
        TypeFactory<?> factory = TypeFactory.defaultInstance();
        JavaType typeArg1 = factory.concretizeType(factory.constructType(String.class));

        // TypeParamStash.paramsFor1(null) likely returns null or throws, 
        // but according to the code varLen becomes 0 if vars is null.
        // If vars is null, it throws IllegalArgumentException.
        TypeBindings.create(null, typeArg1);
    }
}
